-- =============================================================================
-- ENTITY UID RULE  (2026-10-05)
--
-- Every entity gets a 6-character, kind-prefixed alphanumeric UID (e.g. H7K2PX = hospital,
-- C4M9TA = corporate) generated BY THE DATABASE on insert. No application code path can create an
-- entity without one, and no two entities -- of any kind, in any table -- can share one.
--
-- Why in the database: the previous rule lived in Sequelize beforeCreate hooks and a JS helper.
-- Raw SQL, bulkCreate and scripts bypassed it entirely, `tenants` (the table every subdomain and
-- tenant gate resolves through) had no UID at all, and users.organization_id held a TENANT id for
-- some users and a CORPORATES id for others, so id 49 meant Madras Medical Mission to one query and
-- Ninjacart to another. A UID carries its kind and resolves through entity_registry, so it cannot
-- be misread.
--
-- Idempotent: safe to re-run. Runs in one transaction; see scripts/ops/apply-entity-uid-rule.mjs.
-- =============================================================================

-- ── 1. The kinds, and their prefixes ─────────────────────────────────────────
CREATE TABLE IF NOT EXISTS entity_kinds (
  kind        text PRIMARY KEY,
  prefix      text NOT NULL CHECK (prefix ~ '^[A-Z]$'),
  label       text NOT NULL,
  is_org      boolean NOT NULL,
  tenant_type text            -- the tenants.type label this kind is stored under, if any
);
-- Organisation prefixes must be unique among organisations, so a UID's first letter alone names
-- its kind. People kinds are allowed to share one (user and patient are both U).
CREATE UNIQUE INDEX IF NOT EXISTS uq_entity_kinds_org_prefix  ON entity_kinds (prefix) WHERE is_org;
CREATE UNIQUE INDEX IF NOT EXISTS uq_entity_kinds_tenant_type ON entity_kinds (tenant_type) WHERE tenant_type IS NOT NULL;

INSERT INTO entity_kinds (kind, prefix, label, is_org, tenant_type) VALUES
  ('corporate',          'C', 'Corporate',          true,  'corporate'),
  ('hospital',           'H', 'Hospital',           true,  'hospital'),
  ('clinic',             'K', 'Clinic',             true,  'clinic'),
  ('lab',                'L', 'Lab',                true,  'lab'),
  ('pharmacy',           'P', 'Pharmacy',           true,  'pharmacy'),
  ('ambulance',          'B', 'Ambulance',          true,  'ambulance'),
  ('homecare',           'M', 'Homecare',           true,  'homecare'),
  ('diagnostic_centre',  'Y', 'Diagnostic centre',  true,  NULL),
  ('ngo',                'G', 'NGO',                true,  'ngo'),
  ('tpa',                'X', 'TPA',                true,  'tpa'),
  ('insurance_company',  'I', 'Insurance company',  true,  'insurer'),
  ('broker',             'V', 'Insurance broker',   true,  'broker'),
  ('wellness_company',   'W', 'Wellness company',   true,  NULL),
  ('psu',                'S', 'PSU',                true,  'psu'),
  ('aggregator',         'Z', 'Aggregator',         true,  'aggregator'),
  ('user',               'U', 'User',               false, NULL),
  ('patient',            'U', 'Patient',            false, NULL),
  ('doctor',             'D', 'Doctor',             false, NULL),
  ('nurse',              'N', 'Nurse',              false, NULL),
  ('assistant',          'A', 'Doctor assistant',   false, NULL),
  ('team',               'T', 'Team member',        false, NULL),
  ('corporate_employee', 'E', 'Corporate employee', false, NULL),
  ('ohc',                'O', 'Occupational health centre', false, NULL),
  ('admin',              'R', 'Admin / system',     false, NULL)
ON CONFLICT (kind) DO NOTHING;

-- ── 2. The registry: one row per UID, across every table ─────────────────────
CREATE TABLE IF NOT EXISTS entity_registry (
  uid          text PRIMARY KEY CHECK (uid ~ '^[A-Z0-9]{6}$'),
  kind         text NOT NULL REFERENCES entity_kinds (kind),
  source_table text NOT NULL,
  source_id    bigint NOT NULL,
  legacy       boolean NOT NULL DEFAULT false,   -- issued before the rule, prefix may not match its kind
  created_at   timestamptz NOT NULL DEFAULT now(),
  retired_at   timestamptz                       -- set when the entity is deleted OR re-issued; a uid is never reused
);
-- One ACTIVE uid per entity. A partial index rather than UNIQUE (source_table, source_id), so a
-- re-issued entity can keep its old, retired row next to the new active one.
CREATE UNIQUE INDEX IF NOT EXISTS uq_entity_registry_active_source
  ON entity_registry (source_table, source_id) WHERE retired_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_entity_registry_kind ON entity_registry (kind);

-- A re-issued uid keeps working: the old value is retired (never reusable) and resolves to its
-- replacement, so an id that was printed, shared or bookmarked is not broken by a correction.
CREATE TABLE IF NOT EXISTS entity_uid_aliases (
  old_uid    text PRIMARY KEY REFERENCES entity_registry (uid),
  uid        text NOT NULL REFERENCES entity_registry (uid),
  reason     text,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_entity_uid_aliases_uid ON entity_uid_aliases (uid);

-- Which tables the rule has been attached to. The verifier reads this to find tables that have a
-- unique_id-style column but were never attached.
CREATE TABLE IF NOT EXISTS entity_uid_rules (
  table_name  text PRIMARY KEY,
  kind        text,                 -- NULL when the kind comes from a type column (tenants)
  column_name text NOT NULL,
  strict      boolean NOT NULL,
  type_column text,
  attached_at timestamptz NOT NULL DEFAULT now()
);

-- ── 3. Generation ────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION entity_kind_for_tenant_type(p_type text) RETURNS text
LANGUAGE sql STABLE AS $$ SELECT kind FROM entity_kinds WHERE tenant_type = p_type $$;

CREATE OR REPLACE FUNCTION generate_entity_uid(p_kind text) RETURNS text
LANGUAGE plpgsql AS $fn$
DECLARE
  v_prefix text;
  -- Same alphabet as utils/uniqueIdGenerator.js: no 0/O/1/I so an id read aloud or off a printout
  -- cannot be mistaken.
  v_chars constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  v_uid   text;
  v_i     int;
  v_tries int := 0;
BEGIN
  SELECT prefix INTO v_prefix FROM entity_kinds WHERE kind = p_kind;
  IF v_prefix IS NULL THEN
    RAISE EXCEPTION 'entity_uid: unknown entity kind "%"', p_kind USING ERRCODE = '22023';
  END IF;
  LOOP
    v_uid := v_prefix;
    FOR v_i IN 1..5 LOOP
      v_uid := v_uid || substr(v_chars, 1 + floor(random() * 32)::int, 1);
    END LOOP;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM entity_registry WHERE uid = v_uid);
    v_tries := v_tries + 1;
    IF v_tries > 200 THEN
      RAISE EXCEPTION 'entity_uid: no free uid for kind "%" after 200 tries', p_kind;
    END IF;
  END LOOP;
  RETURN v_uid;
END
$fn$;

-- ── 4. The trigger functions ─────────────────────────────────────────────────
-- BEFORE INSERT / BEFORE UPDATE. Registration happens HERE, not in an AFTER trigger: AFTER ROW
-- triggers of a multi-row INSERT fire only after every BEFORE trigger has run, so a 10,000-row
-- bulk insert would generate all its uids before registering any, and two could collide (expected
-- collisions are n^2 / 2N, about 1.5 per 10k rows in a 32^5 space). Registering immediately makes
-- each generated uid visible to the next row's check.
-- Arguments: kind, column, 'strict'|'relaxed', type_column (the last two may be '' / unused).
CREATE OR REPLACE FUNCTION entity_uid_before() RETURNS trigger
LANGUAGE plpgsql AS $fn$
DECLARE
  v_kind     text    := NULLIF(TG_ARGV[0], '');
  v_col      text    := TG_ARGV[1];
  v_strict   boolean := (TG_ARGV[2] = 'strict');
  v_type_col text    := NULLIF(TG_ARGV[3], '');
  v_new      jsonb   := to_jsonb(NEW);
  v_uid      text    := v_new ->> v_col;
  v_old_uid  text;
  v_prefix   text;
  v_id       bigint  := NULLIF(v_new ->> 'id', '')::bigint;
BEGIN
  IF v_type_col IS NOT NULL THEN
    v_kind := entity_kind_for_tenant_type(v_new ->> v_type_col);
    IF v_kind IS NULL THEN
      RAISE EXCEPTION 'entity_uid: %.% = "%" has no entity kind', TG_TABLE_NAME, v_type_col, v_new ->> v_type_col
        USING ERRCODE = '22023';
    END IF;
  END IF;
  IF v_id IS NULL THEN
    RAISE EXCEPTION 'entity_uid: %.id is NULL; cannot register an entity without a primary key', TG_TABLE_NAME;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    v_old_uid := to_jsonb(OLD) ->> v_col;
    IF v_old_uid IS NOT NULL THEN
      IF v_uid IS NOT DISTINCT FROM v_old_uid THEN
        RETURN NEW;
      END IF;
      -- The ONLY way a uid may change is reissue_entity_uid(), which sets this transaction-local flag
      -- after retiring the old registry row. Anything else, including a hand-written UPDATE, is refused.
      IF COALESCE(current_setting('app.entity_uid_reissue', true), '') <> 'on' OR v_uid IS NULL THEN
        RAISE EXCEPTION 'entity_uid: %.% is immutable (% -> %); use reissue_entity_uid()', TG_TABLE_NAME, v_col, v_old_uid, v_uid
          USING ERRCODE = '23514';
      END IF;
    END IF;
  END IF;

  IF v_uid IS NULL THEN
    v_uid := generate_entity_uid(v_kind);
    NEW := jsonb_populate_record(NEW, jsonb_build_object(v_col, v_uid));
  ELSE
    IF v_uid !~ '^[A-Z0-9]{6}$' THEN
      RAISE EXCEPTION 'entity_uid: "%" is not a valid uid (6 characters, A-Z and 0-9)', v_uid USING ERRCODE = '23514';
    END IF;
    IF v_strict THEN
      SELECT prefix INTO v_prefix FROM entity_kinds WHERE kind = v_kind;
      IF left(v_uid, 1) <> v_prefix THEN
        RAISE EXCEPTION 'entity_uid: "%" must start with "%" for a % (got "%")', v_uid, v_prefix, v_kind, left(v_uid, 1)
          USING ERRCODE = '23514';
      END IF;
    END IF;
  END IF;

  INSERT INTO entity_registry (uid, kind, source_table, source_id) VALUES (v_uid, v_kind, TG_TABLE_NAME, v_id);
  RETURN NEW;
END
$fn$;

-- AFTER DELETE: a uid is never reused, so the registry row is retired rather than removed.
CREATE OR REPLACE FUNCTION entity_uid_retire() RETURNS trigger
LANGUAGE plpgsql AS $fn$
BEGIN
  UPDATE entity_registry SET retired_at = now()
   WHERE source_table = TG_TABLE_NAME
     AND source_id = (to_jsonb(OLD) ->> 'id')::bigint
     AND retired_at IS NULL;
  RETURN OLD;
END
$fn$;

-- ── 5. attach_entity_uid_rule: put a table under the rule ────────────────────
-- Adds the column if missing, registers every existing uid, generates one for every row without
-- one, makes it NOT NULL + UNIQUE, and installs the triggers. One call per table; this is also how
-- a new entity table is brought under the rule.
--   p_strict    true  -> new uids must carry the kind's prefix (organisations)
--               false -> any well-formed uid is accepted (people tables, which carry role prefixes)
--   p_type_col  for tenants: the column whose value selects the kind
CREATE OR REPLACE FUNCTION attach_entity_uid_rule(
  p_table    text,
  p_kind     text,
  p_col      text    DEFAULT 'unique_id',
  p_strict   boolean DEFAULT true,
  p_type_col text    DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql AS $fn$
DECLARE
  v_reg        regclass;
  v_mode       text := CASE WHEN p_strict THEN 'strict' ELSE 'relaxed' END;
  v_registered bigint := 0;
  v_generated  bigint := 0;
  v_legacy     bigint := 0;
  v_rec        record;
  v_uid        text;
  v_bad        text;
BEGIN
  v_reg := to_regclass(quote_ident(p_table));
  IF v_reg IS NULL THEN
    RAISE EXCEPTION 'attach_entity_uid_rule: table "%" does not exist', p_table;
  END IF;
  IF p_type_col IS NULL AND NOT EXISTS (SELECT 1 FROM entity_kinds WHERE kind = p_kind) THEN
    RAISE EXCEPTION 'attach_entity_uid_rule: unknown kind "%"', p_kind;
  END IF;

  -- Idempotent: drop the triggers first so the backfill below cannot re-register itself.
  EXECUTE format('DROP TRIGGER IF EXISTS trg_entity_uid_bi ON %I', p_table);
  EXECUTE format('DROP TRIGGER IF EXISTS trg_entity_uid_bu ON %I', p_table);
  EXECUTE format('DROP TRIGGER IF EXISTS trg_entity_uid_ad ON %I', p_table);

  EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS %I text', p_table, p_col);

  -- Refuse rather than guess when a tenants row has a type with no kind.
  IF p_type_col IS NOT NULL THEN
    EXECUTE format(
      'SELECT t.%1$I::text FROM %2$I t LEFT JOIN entity_kinds k ON k.tenant_type = t.%1$I::text
        WHERE k.kind IS NULL LIMIT 1', p_type_col, p_table) INTO v_bad;
    IF v_bad IS NOT NULL THEN
      RAISE EXCEPTION 'attach_entity_uid_rule: %.% has value "%" with no entity kind', p_table, p_type_col, v_bad;
    END IF;
  END IF;

  -- 1) Register every uid that already exists. A uid already held by another table raises a
  --    unique_violation and aborts the whole migration, which is what we want.
  IF p_type_col IS NULL THEN
    EXECUTE format($q$
      INSERT INTO entity_registry (uid, kind, source_table, source_id, legacy)
      SELECT t.%1$I, %2$L, %3$L, t.id::bigint,
             (%4$L::boolean AND left(t.%1$I, 1) <> (SELECT prefix FROM entity_kinds WHERE kind = %2$L))
        FROM %3$I t WHERE t.%1$I IS NOT NULL
      ON CONFLICT (source_table, source_id) WHERE retired_at IS NULL DO NOTHING
    $q$, p_col, p_kind, p_table, p_strict);
  ELSE
    EXECUTE format($q$
      INSERT INTO entity_registry (uid, kind, source_table, source_id, legacy)
      SELECT t.%1$I, k.kind, %2$L, t.id::bigint, (%3$L::boolean AND left(t.%1$I, 1) <> k.prefix)
        FROM %2$I t JOIN entity_kinds k ON k.tenant_type = t.%4$I::text
       WHERE t.%1$I IS NOT NULL
      ON CONFLICT (source_table, source_id) WHERE retired_at IS NULL DO NOTHING
    $q$, p_col, p_table, p_strict, p_type_col);
  END IF;
  GET DIAGNOSTICS v_registered = ROW_COUNT;

  EXECUTE format('SELECT count(*) FROM entity_registry WHERE source_table = %L AND legacy', p_table) INTO v_legacy;

  -- 2) Give every row that has none a uid, registering each as it is issued so the next draw sees it.
  IF p_type_col IS NULL THEN
    FOR v_rec IN EXECUTE format('SELECT t.id::bigint AS id, %L::text AS kind FROM %I t WHERE t.%I IS NULL ORDER BY t.id',
                                p_kind, p_table, p_col)
    LOOP
      v_uid := generate_entity_uid(v_rec.kind);
      INSERT INTO entity_registry (uid, kind, source_table, source_id) VALUES (v_uid, v_rec.kind, p_table, v_rec.id);
      EXECUTE format('UPDATE %I SET %I = $1 WHERE id = $2', p_table, p_col) USING v_uid, v_rec.id;
      v_generated := v_generated + 1;
    END LOOP;
  ELSE
    FOR v_rec IN EXECUTE format(
        'SELECT t.id::bigint AS id, k.kind FROM %1$I t JOIN entity_kinds k ON k.tenant_type = t.%2$I::text
          WHERE t.%3$I IS NULL ORDER BY t.id', p_table, p_type_col, p_col)
    LOOP
      v_uid := generate_entity_uid(v_rec.kind);
      INSERT INTO entity_registry (uid, kind, source_table, source_id) VALUES (v_uid, v_rec.kind, p_table, v_rec.id);
      EXECUTE format('UPDATE %I SET %I = $1 WHERE id = $2', p_table, p_col) USING v_uid, v_rec.id;
      v_generated := v_generated + 1;
    END LOOP;
  END IF;

  -- 3) Enforce.
  EXECUTE format('ALTER TABLE %I ALTER COLUMN %I SET NOT NULL', p_table, p_col);
  IF NOT EXISTS (
    SELECT 1 FROM pg_index i JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = ANY (i.indkey)
     WHERE i.indrelid = v_reg AND i.indisunique AND i.indnatts = 1 AND i.indpred IS NULL AND a.attname = p_col
  ) THEN
    EXECUTE format('CREATE UNIQUE INDEX %I ON %I (%I)', 'uq_' || p_table || '_' || p_col, p_table, p_col);
  END IF;

  -- 4) Triggers. The UPDATE trigger only fires when the uid changes or is NULL, so ordinary
  --    updates (last-login stamps and the like) never pay for it.
  EXECUTE format(
    'CREATE TRIGGER trg_entity_uid_bi BEFORE INSERT ON %I FOR EACH ROW
       EXECUTE FUNCTION entity_uid_before(%L, %L, %L, %L)',
    p_table, COALESCE(p_kind, ''), p_col, v_mode, COALESCE(p_type_col, ''));
  EXECUTE format(
    'CREATE TRIGGER trg_entity_uid_bu BEFORE UPDATE ON %1$I FOR EACH ROW
       WHEN (OLD.%2$I IS DISTINCT FROM NEW.%2$I OR NEW.%2$I IS NULL)
       EXECUTE FUNCTION entity_uid_before(%3$L, %2$L, %4$L, %5$L)',
    p_table, p_col, COALESCE(p_kind, ''), v_mode, COALESCE(p_type_col, ''));
  EXECUTE format('CREATE TRIGGER trg_entity_uid_ad AFTER DELETE ON %I FOR EACH ROW EXECUTE FUNCTION entity_uid_retire()', p_table);

  INSERT INTO entity_uid_rules (table_name, kind, column_name, strict, type_column)
  VALUES (p_table, p_kind, p_col, p_strict, p_type_col)
  ON CONFLICT (table_name) DO UPDATE
    SET kind = EXCLUDED.kind, column_name = EXCLUDED.column_name, strict = EXCLUDED.strict,
        type_column = EXCLUDED.type_column, attached_at = now();

  RETURN jsonb_build_object('table', p_table, 'column', p_col, 'registered', v_registered,
                            'generated', v_generated, 'legacy', v_legacy);
END
$fn$;

-- ── 6. attach_uid_reference: the expand step for an integer cross-entity reference ──────────────
-- Adds a uid twin to an integer foreign-key column and keeps the pair consistent. The integer keeps
-- working; what changes is that a write where the two disagree is rejected, so the numeric id can
-- never again point somewhere the uid does not.
CREATE OR REPLACE FUNCTION uid_ref_sync() RETURNS trigger
LANGUAGE plpgsql AS $fn$
DECLARE
  v_int_col text := TG_ARGV[0];
  v_uid_col text := TG_ARGV[1];
  v_target  text := TG_ARGV[2];
  v_tcol    text := TG_ARGV[3];
  v_row     jsonb  := to_jsonb(NEW);
  v_int     bigint := NULLIF(v_row ->> v_int_col, '')::bigint;
  v_uid     text   := v_row ->> v_uid_col;
  v_reg_tbl text;
  v_reg_id  bigint;
  v_found   text;
BEGIN
  IF v_uid IS NOT NULL THEN
    SELECT source_table, source_id INTO v_reg_tbl, v_reg_id FROM entity_registry WHERE uid = v_uid;
    IF v_reg_tbl IS NULL THEN
      RAISE EXCEPTION 'uid_ref: %.% = "%" is not a registered uid', TG_TABLE_NAME, v_uid_col, v_uid USING ERRCODE = '23503';
    END IF;
    IF v_reg_tbl <> v_target THEN
      RAISE EXCEPTION 'uid_ref: %.% = "%" is a % uid, but this column references %',
        TG_TABLE_NAME, v_uid_col, v_uid, v_reg_tbl, v_target USING ERRCODE = '23514';
    END IF;
    IF v_int IS NULL THEN
      NEW := jsonb_populate_record(NEW, jsonb_build_object(v_int_col, v_reg_id));
    ELSIF v_int <> v_reg_id THEN
      RAISE EXCEPTION 'uid_ref: %.% = % but %.% = "%" points at % #%. The integer and the uid must agree.',
        TG_TABLE_NAME, v_int_col, v_int, TG_TABLE_NAME, v_uid_col, v_uid, v_target, v_reg_id USING ERRCODE = '23514';
    END IF;
  ELSIF v_int IS NOT NULL THEN
    EXECUTE format('SELECT %I FROM %I WHERE id = $1', v_tcol, v_target) INTO v_found USING v_int;
    IF v_found IS NOT NULL THEN
      NEW := jsonb_populate_record(NEW, jsonb_build_object(v_uid_col, v_found));
    END IF;
  END IF;
  RETURN NEW;
END
$fn$;

CREATE OR REPLACE FUNCTION attach_uid_reference(
  p_table text, p_int_col text, p_uid_col text, p_target text, p_target_col text DEFAULT 'unique_id'
) RETURNS jsonb
LANGUAGE plpgsql AS $fn$
DECLARE
  v_filled bigint;
BEGIN
  EXECUTE format('DROP TRIGGER IF EXISTS %I ON %I', 'trg_uid_ref_' || p_uid_col, p_table);
  EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS %I text', p_table, p_uid_col);
  EXECUTE format('UPDATE %1$I t SET %2$I = g.%5$I FROM %4$I g WHERE t.%3$I = g.id AND t.%2$I IS NULL',
                 p_table, p_uid_col, p_int_col, p_target, p_target_col);
  GET DIAGNOSTICS v_filled = ROW_COUNT;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_' || p_table || '_' || p_uid_col) THEN
    EXECUTE format('ALTER TABLE %I ADD CONSTRAINT %I FOREIGN KEY (%I) REFERENCES entity_registry (uid)',
                   p_table, 'fk_' || p_table || '_' || p_uid_col, p_uid_col);
  END IF;
  EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON %I (%I)', 'idx_' || p_table || '_' || p_uid_col, p_table, p_uid_col);
  EXECUTE format(
    'CREATE TRIGGER %I BEFORE INSERT OR UPDATE OF %I, %I ON %I FOR EACH ROW EXECUTE FUNCTION uid_ref_sync(%L, %L, %L, %L)',
    'trg_uid_ref_' || p_uid_col, p_int_col, p_uid_col, p_table, p_int_col, p_uid_col, p_target, p_target_col);
  RETURN jsonb_build_object('table', p_table, 'uid_column', p_uid_col, 'filled', v_filled);
END
$fn$;

-- ── 6b. resolve and re-issue ─────────────────────────────────────────────────
-- resolve_entity_uid: the CURRENT uid for any uid ever issued (active, or retired-and-replaced).
CREATE OR REPLACE FUNCTION resolve_entity_uid(p_uid text) RETURNS text
LANGUAGE sql STABLE AS $$
  SELECT CASE
           WHEN EXISTS (SELECT 1 FROM entity_registry WHERE uid = p_uid AND retired_at IS NULL) THEN p_uid
           ELSE (SELECT uid FROM entity_uid_aliases WHERE old_uid = p_uid)
         END
$$;

-- reissue_entity_uid: replace an entity's uid (for example to correct a wrong prefix). The old uid is
-- retired and kept as an alias of the new one, so it keeps resolving. This is the only sanctioned
-- way a uid changes; a hand-written UPDATE is still refused by the immutability trigger.
CREATE OR REPLACE FUNCTION reissue_entity_uid(p_table text, p_id bigint, p_reason text DEFAULT NULL)
RETURNS text
LANGUAGE plpgsql AS $fn$
DECLARE
  v_rule record;
  v_old  text;
  v_kind text;
  v_new  text;
BEGIN
  SELECT * INTO v_rule FROM entity_uid_rules WHERE table_name = p_table;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'reissue_entity_uid: table "%" is not under the entity uid rule', p_table;
  END IF;

  EXECUTE format('SELECT %I FROM %I WHERE id = $1', v_rule.column_name, p_table) INTO v_old USING p_id;
  IF v_old IS NULL THEN
    RAISE EXCEPTION 'reissue_entity_uid: %.id=% not found or has no uid', p_table, p_id;
  END IF;

  SELECT kind INTO v_kind FROM entity_registry WHERE uid = v_old AND retired_at IS NULL;
  IF v_kind IS NULL THEN
    RAISE EXCEPTION 'reissue_entity_uid: % is not an active uid', v_old;
  END IF;

  v_new := generate_entity_uid(v_kind);

  UPDATE entity_registry SET retired_at = now(), legacy = true WHERE uid = v_old AND retired_at IS NULL;
  PERFORM set_config('app.entity_uid_reissue', 'on', true);
  EXECUTE format('UPDATE %I SET %I = $1 WHERE id = $2', p_table, v_rule.column_name) USING v_new, p_id;
  PERFORM set_config('app.entity_uid_reissue', 'off', true);

  -- Flatten: anything that already pointed at the uid being replaced now points at its successor,
  -- so resolve_entity_uid() stays a single hop however many times an entity is re-issued.
  UPDATE entity_uid_aliases SET uid = v_new WHERE uid = v_old;
  INSERT INTO entity_uid_aliases (old_uid, uid, reason) VALUES (v_old, v_new, p_reason);
  RETURN v_new;
END
$fn$;

-- ── 7. Attach the rule ───────────────────────────────────────────────────────
-- Organisations (strict: the prefix must match the kind).
SELECT attach_entity_uid_rule('tenants',             NULL,                'unique_id', true, 'type');
SELECT attach_entity_uid_rule('corporates',          'corporate');
SELECT attach_entity_uid_rule('hospitals',           'hospital');
SELECT attach_entity_uid_rule('labs',                'lab');
SELECT attach_entity_uid_rule('pharmacies',          'pharmacy');
SELECT attach_entity_uid_rule('tpas',                'tpa');
SELECT attach_entity_uid_rule('insurance_companies', 'insurance_company');
SELECT attach_entity_uid_rule('insurance_brokers',   'broker', 'broker_uid');
SELECT attach_entity_uid_rule('ambulances',          'ambulance');
SELECT attach_entity_uid_rule('homecare_providers',  'homecare');
SELECT attach_entity_uid_rule('provider_clinics',    'clinic');
SELECT attach_entity_uid_rule('crm_diagnostic_centres', 'diagnostic_centre');

-- People (relaxed: they carry role-specific prefixes such as E/U/T on users).
SELECT attach_entity_uid_rule('users',               'user',               'unique_id', false);
SELECT attach_entity_uid_rule('patients',            'patient',            'unique_id', false);
SELECT attach_entity_uid_rule('doctors',             'doctor',             'unique_id', false);
SELECT attach_entity_uid_rule('nurses',              'nurse',              'unique_id', false);
SELECT attach_entity_uid_rule('doctor_assistants',   'assistant',          'unique_id', false);
SELECT attach_entity_uid_rule('team_members',        'team',               'unique_id', false);
SELECT attach_entity_uid_rule('corporate_employees', 'corporate_employee', 'unique_id', false);

-- ── 8. The uid twins that remove the tenant-vs-corporate ambiguity ───────────
-- corporates.tenant_id has always meant "tenants.id", so its twin can be filled mechanically.
SELECT attach_uid_reference('corporates', 'tenant_id', 'tenant_uid', 'tenants');

-- users.organization_id is NOT filled mechanically: it holds a tenants id for some users and a
-- corporates id for others, which is the very ambiguity being removed. The column is added with
-- a foreign key into the registry and populated by a reviewed script
-- (scripts/ops/backfill-organization-uid.mjs), not guessed here.
ALTER TABLE users ADD COLUMN IF NOT EXISTS organization_uid text;
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_users_organization_uid') THEN
    ALTER TABLE users ADD CONSTRAINT fk_users_organization_uid
      FOREIGN KEY (organization_uid) REFERENCES entity_registry (uid);
  END IF;
END $$;
CREATE INDEX IF NOT EXISTS idx_users_organization_uid ON users (organization_uid);
